baseCss:
.aha-features{
  container:aha-features / inline-size;
  background:var(--aha-white);
  color:var(--aha-text-default);
  font-family:var(--aha-font-product);
}
.aha-features *{box-sizing:border-box}
.aha-features--accent{box-shadow:inset 0 0 0 100vmax var(--aha-bg-accent)}
.aha-features--accent .aha-features__icon{background:var(--aha-white)}
.aha-features .aha-marketing-cards{background:transparent}
.aha-features .aha-marketing-cards__grid{max-width:none;padding:0}
:where(.aha-features) :is(h2,h3,p,ul,ol,figure){margin:0;padding:0}
:where(.aha-features) :is(ul,ol){list-style:none}
.aha-features__inner{--aha-web-gutter:var(--aha-space-64);max-width:1280px;margin:0 auto;padding:var(--aha-space-96) var(--aha-web-gutter)}
.aha-features__header{max-width:720px;margin:0 0 var(--aha-space-64)}
.aha-features__header--center{margin-inline:auto;text-align:center}
.aha-features__title{
  margin:0 0 var(--aha-space-20);
  font-size:var(--aha-size-h2);
  line-height:var(--aha-line-height-heading);
  font-weight:var(--aha-weight-semibold);
  letter-spacing:var(--aha-letter-spacing-headlines);
  color:var(--aha-text-default);
}
.aha-features__lead{
  max-width:44ch;
  font-size:clamp(var(--aha-size-l),1.4vw,var(--aha-size-xl));
  line-height:var(--aha-line-height-body);
  color:var(--aha-text-secondary);
}
.aha-features__header--center .aha-features__lead{margin-inline:auto}
.aha-features__stack{display:flex;flex-direction:column;align-items:flex-start;gap:var(--aha-space-12)}
.aha-features__icon{
  display:flex;align-items:center;justify-content:center;flex:none;
  width:var(--aha-space-48);height:var(--aha-space-48);
  border-radius:var(--aha-radius-default);
  background:var(--aha-bg-accent);color:var(--aha-color-primary);
}
.aha-features__item-title{
  font-size:var(--aha-size-xl);
  font-weight:var(--aha-weight-semibold);
  line-height:var(--aha-line-height-heading);
  color:var(--aha-text-default);
}
.aha-features__item-text{
  font-size:var(--aha-size-l);
  line-height:var(--aha-line-height-body);
  color:var(--aha-text-secondary);
}
.aha-features__list{display:flex;flex-direction:column;gap:var(--aha-space-32)}
.aha-features__list-item{display:flex;align-items:flex-start;gap:var(--aha-space-16)}
.aha-features__list-item .aha-features__stack{padding-top:var(--aha-space-12)}
.aha-features__column{display:flex;flex-direction:column;gap:var(--aha-space-48);min-width:0}
.aha-features__column .aha-features__cta{margin-top:0}
.aha-features__column{display:flex;flex-direction:column;gap:var(--aha-space-48);min-width:0}
.aha-features__column .aha-features__cta{margin-top:0}
.aha-features__cta{display:flex;flex-wrap:wrap;justify-content:center;gap:var(--aha-space-12);margin-top:var(--aha-space-48)}
.aha-features__cta--start{justify-content:flex-start}
.aha-features__actions{display:flex;flex-wrap:wrap;gap:var(--aha-space-12);margin-top:var(--aha-space-32)}
.aha-features__photo{
  display:flex;align-items:center;justify-content:center;
  width:100%;
  background:var(--aha-bg-container-secondary);
  border-radius:var(--aha-radius-marketing);
  color:var(--aha-icon-muted);
  overflow:hidden;
}
.aha-features__frame{width:100%;height:100%;overflow:hidden;border-radius:var(--aha-radius-marketing)}
.aha-features__frame>img{display:block;width:100%;height:100%;object-fit:cover}
.aha-features__photo--4x3{aspect-ratio:4 / 3}
.aha-features__photo--3x4{aspect-ratio:3 / 4}
.aha-features__photo img{display:block;width:100%;height:100%;object-fit:cover}
.aha-features__photo--fill{aspect-ratio:auto;background:none}
.aha-features__photo--fill img{height:auto;object-fit:fill}
.aha-features__photo--pink-frame{position:relative;background:var(--aha-vivid-pink-100)}
.aha-features__splash{position:absolute;inset:0;overflow:hidden;container-type:size;pointer-events:none;--splash-across:.5;--splash-width:calc(4.5*min(100cqw,100cqh))}
@supports (width:calc(1px*sqrt(4)*tan(atan2(1px,1px)))){
  .aha-features__splash{--splash-width:calc(4.5*min(100cqw,100cqh)*sqrt(max(1,tan(atan2(100cqw,100cqh))*9/16,9/16/tan(atan2(100cqw,100cqh)))))}
}
.aha-features__splash>img{position:absolute;display:block;max-width:none;height:auto;width:var(--splash-width);left:calc(var(--splash-across)*100cqw - var(--splash-width)*0.516209);top:calc(55cqh - var(--splash-width)*0.418953)}
.aha-features__photo .aha-features__splash>img{height:auto;object-fit:fill}
.aha-features__photo--pink-frame>.aha-features__shot{position:relative;width:auto;height:auto;max-width:calc(100% - 2*var(--aha-space-32));max-height:calc(100% - 2*var(--aha-space-32));object-fit:contain;border-radius:var(--aha-radius-lg)}
@container aha-features (max-width:991px){
  .aha-features__title{font-size:var(--aha-size-h3)}
}
@container aha-features (max-width:767px){
  .aha-features__inner{--aha-web-gutter:var(--aha-space-24);padding:var(--aha-space-48) var(--aha-web-gutter)}
}
@container aha-features (max-width:479px){
  .aha-features__photo--pink-frame>.aha-features__shot{max-width:calc(100% - 2*var(--aha-space-16));max-height:calc(100% - 2*var(--aha-space-16))}
  .aha-features__inner{--aha-web-gutter:var(--aha-space-16);padding:var(--aha-space-32) var(--aha-web-gutter)}
  .aha-features__title{font-size:var(--aha-size-h4)}
  .aha-features__actions{margin-top:var(--aha-space-24)}
  .aha-features__cta{margin-top:var(--aha-space-32)}
}
@container aha-features (min-width:992px){
  .aha-features__grid:has(>:first-child:last-child){grid-template-columns:minmax(0,36rem);justify-content:center}
  .aha-features__grid:has(>:nth-child(2):last-child),.aha-features__grid:has(>:nth-child(4):last-child){grid-template-columns:repeat(2,minmax(0,1fr))}
  .aha-features__grid:has(>:nth-child(3n+1):last-child:nth-child(n+7))>:last-child{grid-column:2}
  .aha-features__grid:has(>:nth-child(3n+2):last-child:nth-child(n+5)){grid-template-columns:repeat(6,minmax(0,1fr))}
  .aha-features__grid:has(>:nth-child(3n+2):last-child:nth-child(n+5))>*{grid-column:span 2}
  .aha-features__grid:has(>:nth-child(3n+2):last-child:nth-child(n+5))>:nth-last-child(2){grid-column:2 / span 2}
  .aha-features__grid:has(>:nth-child(3n+2):last-child:nth-child(n+5))>:last-child{grid-column:4 / span 2}
}
@container aha-features (min-width:768px) and (max-width:991px){
  .aha-features__grid:has(>:nth-child(odd):last-child)>:last-child{grid-column:1 / -1;justify-self:center;width:calc(50% - var(--aha-space-16))}
}
.aha-features__visually-hidden{
  position:absolute;width:1px;height:1px;margin:-1px;padding:0;
  overflow:hidden;clip-path:inset(50%);white-space:nowrap;
}

layouts.css:
.aha-features--alternating-screenshots .aha-features__rows{display:flex;flex-direction:column;gap:var(--aha-space-96)}
.aha-features--alternating-screenshots .aha-features__row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--aha-space-64);align-items:center}
.aha-features--alternating-screenshots .aha-features__row-title{
  font-size:var(--aha-size-h4);
  line-height:var(--aha-line-height-heading);
  font-weight:var(--aha-weight-semibold);
  letter-spacing:var(--aha-letter-spacing-headlines);
  color:var(--aha-text-default);
}
.aha-features--alternating-screenshots .aha-features__row-text{
  font-size:clamp(var(--aha-size-l),1.4vw,var(--aha-size-xl));
  line-height:var(--aha-line-height-body);
  color:var(--aha-text-secondary);
}
.aha-features--alternating-screenshots .aha-features__row:nth-child(even) .aha-features__visual{order:-1}
@container aha-features (max-width:991px){
  .aha-features--alternating-screenshots .aha-features__row{grid-template-columns:minmax(0,1fr);gap:var(--aha-space-32)}
  .aha-features--alternating-screenshots .aha-features__row:nth-child(even) .aha-features__visual{order:0}
  .aha-features--alternating-screenshots .aha-features__rows{gap:var(--aha-space-64)}
}
@container aha-features (max-width:479px){
  .aha-features--alternating-screenshots .aha-features__row-title{font-size:var(--aha-size-xl)}
}

.aha-features--tabs-screenshots .aha-features__tabs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--aha-space-48) var(--aha-space-64);align-items:start}
.aha-features--tabs-screenshots .aha-features__column{display:grid;grid-row:1 / span 2;grid-template-rows:subgrid;align-self:stretch}
.aha-features--tabs-screenshots .aha-features__tabpanels{grid-column:2;grid-row:1}
.aha-features--tabs-screenshots .aha-features__tablist{display:flex;flex-direction:column}
.aha-features--tabs-screenshots .aha-features__tab{
  display:flex;flex-direction:column;flex:1 1 auto;justify-content:center;align-items:flex-start;gap:var(--aha-space-12);
  width:100%;
  padding:var(--aha-space-16) var(--aha-space-20);
  border:0;border-left:var(--aha-space-2) solid var(--aha-border-default);
  background:none;
  font-family:inherit;text-align:left;
  cursor:pointer;
  transition:border-color var(--aha-motion-mid) var(--aha-ease-in-out);
}
.aha-features--tabs-screenshots .aha-features__tab:hover{border-left-color:var(--aha-border-hover)}
.aha-features--tabs-screenshots .aha-features__tab[aria-selected="true"]{border-left-color:var(--aha-color-primary)}
.aha-features--tabs-screenshots .aha-features__tab:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2);border-radius:var(--aha-radius-xs)}
.aha-features--tabs-screenshots .aha-features__tabpanels{min-width:0}
@media (prefers-reduced-motion:reduce){
  .aha-features--tabs-screenshots .aha-features__tab{transition:none}
}
@container aha-features (max-width:991px){
  .aha-features--tabs-screenshots .aha-features__tabs{grid-template-columns:minmax(0,1fr)}
  .aha-features--tabs-screenshots .aha-features__column{display:flex;flex-direction:column;grid-row:auto;grid-template-rows:none;gap:var(--aha-space-48)}
  .aha-features--tabs-screenshots .aha-features__tabpanels{grid-column:auto;grid-row:auto}
}

.aha-features--compact .aha-features__inner{padding-block:var(--aha-space-48)}
.aha-features--compact .aha-features__header{margin:0 auto var(--aha-space-32)}
.aha-features--compact .aha-features__title{margin-bottom:0}
@container aha-features (max-width:479px){
  .aha-features--compact .aha-features__inner{padding-block:var(--aha-space-32)}
}
.aha-features__htabs{display:flex;flex-direction:column;gap:var(--aha-space-24)}
.aha-features__htablist{/* ds-lint-allow: overflow-x-scroll (tab row scrolls sideways on a phone, by design) */display:flex;gap:var(--aha-space-8);overflow-x:auto;scrollbar-width:none;border-bottom:1px solid var(--aha-border-default)}
.aha-features__htab{
  display:inline-flex;align-items:center;gap:var(--aha-space-8);flex:none;
  padding:var(--aha-space-12) var(--aha-space-16);
  border:0;border-bottom:var(--aha-space-2) solid transparent;margin-bottom:-1px;
  background:none;font-family:inherit;font-size:var(--aha-size-l);font-weight:var(--aha-weight-semibold);
  color:var(--aha-text-secondary);cursor:pointer;
  transition:border-color var(--aha-motion-mid) var(--aha-ease-in-out),color var(--aha-motion-mid) var(--aha-ease-in-out);
}
.aha-features__htab:not([aria-selected="true"]):hover{border-bottom-color:var(--aha-border-hover);color:var(--aha-text-default)}
.aha-features__htab[aria-selected="true"]{border-bottom-color:var(--aha-color-primary);color:var(--aha-text-default)}
.aha-features__htab aha-icon{color:var(--aha-color-primary)}
.aha-features__htab:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:calc(-1 * var(--aha-space-2));border-radius:var(--aha-radius-xs)}
.aha-features__htabpanel{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:var(--aha-space-48);align-items:center}
.aha-features__htabpanel[hidden]{display:none}
@media (prefers-reduced-motion:reduce){
  .aha-features__htab{transition:none}
}
@container aha-features (max-width:991px){
  .aha-features__htabpanel{grid-template-columns:minmax(0,1fr);gap:var(--aha-space-24)}
}
.aha-features__htab:first-child{margin-left:auto}
.aha-features__htab:last-child{margin-right:auto}

.aha-features--compact .aha-features__inner{padding-block:var(--aha-space-48)}
.aha-features--compact .aha-features__header{margin:0 auto var(--aha-space-32)}
.aha-features--compact .aha-features__title{margin-bottom:0}
@container aha-features (max-width:479px){
  .aha-features--compact .aha-features__inner{padding-block:var(--aha-space-32)}
}
.aha-features__viewport{/* ds-lint-allow: overflow-x-scroll (the card scroller is the layout) */overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;padding:var(--aha-space-12) 0;margin:calc(-1 * var(--aha-space-12)) 0;border-radius:var(--aha-radius-lg)}
.aha-features__viewport:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2)}
.aha-features__track{display:flex;gap:var(--aha-space-24)}
.aha-features__track>li{flex:0 0 calc((100% - 3 * var(--aha-space-24)) / 3.3);scroll-snap-align:start;scroll-margin-inline:0;min-width:0}
.aha-features__controls{display:flex;align-items:center;justify-content:space-between;gap:var(--aha-space-16);margin-top:var(--aha-space-24)}
.aha-features__controls-buttons{display:flex;gap:var(--aha-space-8)}
.aha-features__position{font-size:var(--aha-size-default);color:var(--aha-text-secondary)}
@container aha-features (max-width:991px){
  .aha-features__track>li{flex-basis:calc((100% - var(--aha-space-24)) / 2.2)}
}
@container aha-features (max-width:767px){
  .aha-features__track>li{flex-basis:calc((100% - var(--aha-space-24)) / 1.15)}
}

.aha-features--compact .aha-features__inner{padding-block:var(--aha-space-48)}
.aha-features--compact .aha-features__header{margin:0 auto var(--aha-space-32)}
.aha-features--compact .aha-features__title{margin-bottom:0}
@container aha-features (max-width:479px){
  .aha-features--compact .aha-features__inner{padding-block:var(--aha-space-32)}
}
