.aha-features__track>li{flex:0 0 calc((100% - 3 * var(--aha-space-24)) / 3.3);scroll-snap-align:start;scroll-margin-inline:0;min-width:0}
.aha-features__controls{display:flex;align-items:center;justify-content:space-between;gap:var(--aha-space-16);margin-top:var(--aha-space-24)}
.aha-features__controls-buttons{display:flex;gap:var(--aha-space-8)}
.aha-features__position{font-size:var(--aha-size-default);color:var(--aha-text-secondary)}
@container aha-features (max-width:991px){
  .aha-features__track>li{flex-basis:calc((100% - var(--aha-space-24)) / 2.2)}
}
@container aha-features (max-width:767px){
  .aha-features__track>li{flex-basis:calc((100% - var(--aha-space-24)) / 1.15)}
}

.aha-features__track{list-style:none;margin:0;padding:0}
.aha-features__track>li>.aha-marketing-card{height:100%}
.aha-marketing-card__media--scroller{margin-top:auto}

.aha-features__sticky{display:flex;flex-direction:column;gap:var(--aha-space-32)}
.aha-features__sticky-card{position:sticky;top:var(--aha-space-32);display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:var(--aha-space-48);align-items:center;padding:var(--aha-space-32);border:1px solid var(--aha-border-default);border-radius:var(--aha-radius-marketing);background:var(--aha-white)}
.aha-features__sticky-card:nth-child(2){top:calc(var(--aha-space-32) + var(--aha-space-16))}
.aha-features__sticky-card:nth-child(3){top:calc(var(--aha-space-32) + 2 * var(--aha-space-16))}
.aha-features__sticky-card:nth-child(4){top:calc(var(--aha-space-32) + 3 * var(--aha-space-16))}
.aha-features__sticky-card:nth-child(5){top:calc(var(--aha-space-32) + 4 * var(--aha-space-16))}
.aha-features__sticky-image{display:block;width:100%;height:auto;aspect-ratio:16 / 9;object-fit:cover;border-radius:var(--aha-radius-lg);background:var(--aha-bg-container-secondary)}
.aha-features__sticky-text{display:flex;flex-direction:column;gap:var(--aha-space-12)}
.aha-features__sticky-step{font-size:var(--aha-size-sm);font-weight:var(--aha-weight-semibold);letter-spacing:var(--aha-letter-spacing-subheadings);text-transform:uppercase;color:var(--aha-color-primary)}
.aha-features__sticky-title{font-size:var(--aha-size-h4);font-weight:var(--aha-weight-semibold);line-height:var(--aha-line-height-heading);color:var(--aha-text-default)}
.aha-features__sticky-description{font-size:var(--aha-size-l);line-height:var(--aha-line-height-body);color:var(--aha-text-secondary)}
@container aha-features (max-width:767px){
  .aha-features__sticky-card{grid-template-columns:minmax(0,1fr);gap:var(--aha-space-20);padding:var(--aha-space-24)}
}
@container aha-features (max-width:479px){
  .aha-features__sticky{gap:var(--aha-space-16)}
  .aha-features__sticky-card{padding:var(--aha-space-16)}
  .aha-features__sticky-title{font-size:var(--aha-size-h5)}
}
